/* eslint-disable @next/next/no-img-element */
/** India base map as a static, cached SVG (generated by scripts/build-maps.mjs; CC BY 4.0 @svg-maps/india). */
export function IndiaMapBase({ className = "" }: { className?: string }) {
  return <img src="/maps/india.svg" alt="" aria-hidden className={className} width={612} height={696} loading="lazy" decoding="async" />;
}
